const [form, setForm] = useState({ email: "", agree: false })
<input value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} />
<input type="checkbox" checked={form.agree} onChange={e => setForm({ ...form, agree: e.target.checked })} />

function Search({ onSearch }: { onSearch: (q: string) => void }) {
  return <form onSubmit={e => {
    e.preventDefault()
    onSearch(String(new FormData(e.currentTarget).get("q") ?? ""))
  }}>
    <input name="q" defaultValue="" aria-label="Search" />
  </form>
}
